import type { Page } from "@playwright/test";
import { test, expect } from "./coverage";

// The public validation page, /validation/ — generated by
// examples/validation/run.mjs --report (which also checks, on every CI run, that
// its numbers still match the engine). These tests check that the page is served
// and complete, and that its in-app reproduction holds: opening the linked
// example in KoFEM and solving it shows exactly the value the page publishes.

type Published = {
  engine: string;
  cases: { id: string; name: string }[];
  convergence: { id: string }[];
  reproduce: { galleryId: string; field: string; stat: string };
};

async function published(page: Page): Promise<Published> {
  const res = await page.request.get("/validation/results.json");
  expect(res.ok()).toBe(true);
  return (await res.json()) as Published;
}

// The value the app's Result summary shows for `stat` (e.g. "Max Ux").
function summaryValue(page: Page, stat: string) {
  return page
    .getByText(stat, { exact: true })
    .locator("xpath=following-sibling::span[1]");
}

async function showField(page: Page, field: string) {
  await page.getByTestId("tree-plot-1").click();
  await page.getByTestId("plot-field").selectOption(field);
}

test("/validation/ lists every benchmark, its convergence studies and the disclaimer", async ({
  page,
}) => {
  const data = await published(page);
  await page.goto("/validation/");

  await expect(
    page.getByRole("heading", { level: 1, name: "Validation benchmarks" }),
  ).toBeVisible();
  await expect(page.locator('link[rel="canonical"]')).toHaveAttribute(
    "href",
    "https://kofem.org/validation/",
  );
  await expect(page.locator('meta[name="description"]')).toHaveAttribute(
    "content",
    /benchmark/,
  );
  await expect(page.getByTestId("disclaimer")).toContainText(
    "not certified for safety-critical design",
  );
  await expect(page.locator(".meta")).toContainText(`engine ${data.engine}`);

  // One section per case, in the order of the published data, each with its
  // KoFEM value — and one results-table row per case.
  const sections = page.locator("[data-case]");
  await expect(sections).toHaveCount(data.cases.length);
  expect(
    await sections.evaluateAll((els) =>
      els.map((e) => e.getAttribute("data-case")),
    ),
  ).toEqual(data.cases.map((c) => c.id));
  for (const c of data.cases) {
    const section = page.locator(`[data-case="${c.id}"]`);
    await expect(section.getByRole("heading", { level: 3 })).toHaveText(c.name);
    await expect(section.getByTestId("fe-value")).not.toBeEmpty();
    await expect(
      page.locator("table.results").getByRole("link", { name: c.name }),
    ).toHaveAttribute("href", `#case-${c.id}`);
  }

  // Each convergence study renders its chart.
  await expect(page.locator("[data-study]")).toHaveCount(
    data.convergence.length,
  );
  for (const s of data.convergence)
    await expect(
      page.locator(`[data-study="${s.id}"] figure.chart svg`),
    ).toBeVisible();

  // Listed for crawlers.
  const sitemap = await page.request.get("/sitemap.xml");
  expect(await sitemap.text()).toContain(
    "<loc>https://kofem.org/validation/</loc>",
  );
});

test("the page's in-app reproduction shows the published value", async ({
  page,
}) => {
  test.setTimeout(90_000);
  const { reproduce } = await published(page);
  await page.goto("/validation/");

  const readout = page.getByTestId("app-readout");
  await expect(readout).toHaveAttribute("data-stat", reproduce.stat);
  const value = await readout.getAttribute("data-value");
  if (!value)
    throw new Error("the page's app readout is missing its data-value");
  expect(value).toMatch(/^-?\d\.\d{3}e[+-]\d+ mm$/);

  // The page's link opens the gallery example in the app.
  await page.getByTestId("reproduce-open").click();
  await expect(page).toHaveURL(`/app/?example=${reproduce.galleryId}`);
  await expect(page.locator("nav")).toBeVisible();
  await page.waitForFunction(
    () =>
      (
        window as unknown as {
          __kofemStore?: { getState(): { nodes: unknown[] } };
        }
      ).__kofemStore?.getState().nodes.length,
    null,
    { timeout: 30_000 },
  );

  // Solve it in the browser (Studies → Static 1 → Run static solve), as the
  // page instructs: the example ships a stored result, which the solve replaces.
  await page.evaluate(() => {
    const win = window as unknown as {
      __kofemStore: { getState(): { result: unknown } };
      __storedResult: unknown;
    };
    win.__storedResult = win.__kofemStore.getState().result;
  });
  await page.getByTestId("tree-study-1").click();
  await page.getByRole("button", { name: /Run static solve/ }).click();
  await page.waitForFunction(
    () => {
      const win = window as unknown as {
        __kofemStore: { getState(): { result: unknown } };
        __storedResult: unknown;
      };
      const { result } = win.__kofemStore.getState();
      return result !== null && result !== win.__storedResult;
    },
    null,
    { timeout: 60_000 },
  );
  await showField(page, reproduce.field);
  await expect(summaryValue(page, reproduce.stat)).toHaveText(value);
});
